import itertools

def is_kawaii(sequence):
    N = len(sequence)

    # Handle empty sequence, though N>=3 here
    if not sequence:
        return True

    max_k = max(sequence)

    # Check conditions for k = 2 up to max_k
    for k in range(2, max_k + 1):
        # Check if k appears
        if k in sequence:
            # Condition 1: k-1 must appear
            if (k - 1) not in sequence:
                return False

            # Condition 2: first occurrence of k-1 comes before last occurrence of k

            # Find first occurrence of k-1
            first_k_minus_1 = -1
            for i in range(N):
                if sequence[i] == k - 1:
                    first_k_minus_1 = i
                    break

            # Find last occurrence of k
            last_k = -1
            for i in range(N - 1, -1, -1):
                if sequence[i] == k:
                    last_k = i
                    break

            # Indices are 0-based. We need first_k_minus_1 < last_k.
            if first_k_minus_1 >= last_k:
                return False

    return True

# Task 1: N=3, S'={1, 2, 3}
N3_count = 0
for seq in itertools.product([1, 2, 3], repeat=3):
    if is_kawaii(seq):
        N3_count += 1

print(f"N=3 count (S'={{{'1, 2, 3'}}}): {N3_count}")

